import { q } from "../db";
import { dayStart, isIsoDate, labelToMinutes } from "../time";
import { RESERVATION_SELECT, type ReservationRow } from "./reservations";

export type ListFilters = {
  q?: string;
  from?: string;            // business-local dates, inclusive
  to?: string;
  status?: string[];
  checkedIn?: boolean;
  timeFrom?: number;        // minutes after local midnight
  timeTo?: number;
  partyMin?: number;
  partyMax?: number;
  serviceId?: string;
  source?: string;
  sort?: "time" | "time_desc" | "created";
  limit?: number;
  offset?: number;
};

const STATUSES = ["pending", "confirmed", "checked_in", "completed", "cancelled", "no_show"];

/** Filtered, paginated reservation list for one business. All values are bound parameters. */
export async function listReservations(businessId: string, tz: string, f: ListFilters): Promise<{ rows: ReservationRow[]; total: number }> {
  const where: string[] = ["r.business_id = $1"];
  const params: unknown[] = [businessId];
  const add = (sql: string, ...vals: unknown[]) => {
    let s = sql;
    for (const v of vals) { params.push(v); s = s.replace("?", `$${params.length}`); }
    where.push(s);
  };

  if (f.from) add("r.starts_at >= ?", dayStart(f.from, tz).toJSDate());
  if (f.to) add("r.starts_at < ?", dayStart(f.to, tz).plus({ days: 1 }).toJSDate());
  const statuses = (f.status ?? []).filter((s) => STATUSES.includes(s));
  if (statuses.length) add("r.status = ANY(?)", statuses);
  if (f.checkedIn === true) add("r.checked_in_at IS NOT NULL");
  if (f.checkedIn === false) add("r.checked_in_at IS NULL");
  if (f.partyMin) add("r.party_size >= ?", f.partyMin);
  if (f.partyMax) add("r.party_size <= ?", f.partyMax);
  if (f.serviceId && /^[0-9a-f-]{36}$/i.test(f.serviceId)) add("r.service_id = ?", f.serviceId);
  if (f.source && ["web", "ai", "staff"].includes(f.source)) add("r.source = ?", f.source);
  if (f.timeFrom !== undefined || f.timeTo !== undefined) {
    params.push(tz);
    const local = `(extract(hour from r.starts_at AT TIME ZONE $${params.length}) * 60 + extract(minute from r.starts_at AT TIME ZONE $${params.length}))`;
    if (f.timeFrom !== undefined) add(`${local} >= ?`, f.timeFrom);
    if (f.timeTo !== undefined) add(`${local} <= ?`, f.timeTo);
  }

  const term = (f.q ?? "").trim().slice(0, 80);
  if (term) {
    const like = `%${term.toLowerCase().replace(/[\\%_]/g, "\\$&")}%`;
    const ref = term.toUpperCase().replace(/[^A-Z0-9]/g, "");
    const digits = term.replace(/\D/g, "");
    const parts: string[] = [];
    params.push(like); parts.push(`lower(c.name) LIKE $${params.length}`);
    if (ref.length >= 3) { params.push(`%${ref}%`); parts.push(`r.reference LIKE $${params.length}`); }
    // Phone search needs at least 4 digits so short numbers cannot be used to enumerate customers.
    if (digits.length >= 4 && digits.length === term.replace(/[\s+().-]/g, "").length) { params.push(`%${digits}%`); parts.push(`c.phone_digits LIKE $${params.length}`); }
    where.push(`(${parts.join(" OR ")})`);
  }

  const order = f.sort === "created" ? "r.created_at DESC" : f.sort === "time_desc" ? "r.starts_at DESC, r.id" : "r.starts_at ASC, r.id";
  const limit = Math.min(Math.max(f.limit ?? 50, 1), 200);
  const offset = Math.max(f.offset ?? 0, 0);
  const w = where.join(" AND ");
  const [rows, count] = await Promise.all([
    q<ReservationRow>(`${RESERVATION_SELECT} WHERE ${w} ORDER BY ${order} LIMIT ${limit} OFFSET ${offset}`, params),
    q<{ n: number }>(`SELECT count(*)::int AS n FROM reservations r JOIN customers c ON c.id = r.customer_id WHERE ${w}`, params),
  ]);
  return { rows, total: count[0].n };
}

/** Phone numbers are shown in full only to roles that need them. */
export function maskPhone(phone: string | null, full: boolean): string | null {
  if (!phone) return null;
  if (full) return phone;
  const d = phone.replace(/\D/g, "");
  return d.length <= 4 ? "••••" : `••• ${d.slice(-4)}`;
}
export function maskEmail(email: string | null, full: boolean): string | null {
  if (!email) return null;
  if (full) return email;
  const [u, dom] = email.split("@");
  return `${u.slice(0, 1)}•••@${dom}`;
}

/** Read list filters from a query string (shared by the API and the server-rendered list). */
export function parseFilters(sp: URLSearchParams): ListFilters {
  const int = (k: string) => { const v = Number(sp.get(k)); return Number.isInteger(v) && v > 0 ? v : undefined; };
  const date = (k: string) => { const v = sp.get(k) ?? ""; return isIsoDate(v) ? v : undefined; };
  const mins = (k: string) => { const v = labelToMinutes(sp.get(k) ?? ""); return v === null ? undefined : v; };
  const ci = sp.get("checkedIn");
  const sort = sp.get("sort");
  return {
    q: sp.get("q") ?? undefined, from: date("from"), to: date("to"),
    status: sp.get("status")?.split(",").filter(Boolean),
    checkedIn: ci === "yes" ? true : ci === "no" ? false : undefined,
    timeFrom: mins("timeFrom"), timeTo: mins("timeTo"), partyMin: int("partyMin"), partyMax: int("partyMax"),
    serviceId: sp.get("service") ?? undefined, source: sp.get("source") ?? undefined,
    sort: sort === "created" || sort === "time_desc" ? sort : "time",
    limit: int("limit"), offset: Number(sp.get("offset")) > 0 ? Number(sp.get("offset")) : 0,
  };
}

