import { cookies } from "next/headers";
import { one, q, tx } from "./db";
import { AppError, forbidden, invalid, notFound, unauthorized } from "./errors";
import { hashPassword, randomToken, sha256, verifyPassword } from "./crypto";
import { env } from "./env";
import { BUSINESS_COLUMNS, type Business } from "./booking/availability";

const COOKIE = "abc_session";
const SESSION_DAYS = 30;

export type User = { id: string; email: string; name: string };
export type Role = "owner" | "manager" | "staff";

// What each role may do. Checked on the server for every request; the UI only hides what would fail.
const PERMISSIONS: Record<Role, string[]> = {
  staff: ["reservations.read", "reservations.create", "checkin", "conversations.read", "ai.toggle"],
  manager: ["reservations.read", "reservations.create", "checkin", "conversations.read",
            "reservations.manage", "settings", "ai.toggle", "customers.full", "customers.erase"],
  owner: ["reservations.read", "reservations.create", "checkin", "conversations.read",
          "reservations.manage", "settings", "ai.toggle", "customers.full", "customers.erase", "team"],
};
export type Permission =
  | "reservations.read" | "reservations.create" | "checkin" | "conversations.read"
  | "reservations.manage" | "settings" | "ai.toggle" | "customers.full" | "customers.erase" | "team";

export const can = (role: Role, p: Permission) => PERMISSIONS[role].includes(p);

export async function registerUser(input: { email: string; name: string; password: string }): Promise<User> {
  const email = input.email.trim().toLowerCase();
  const name = input.name.trim();
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email) || email.length > 160) throw invalid("Please enter a valid email address.");
  if (name.length < 2 || name.length > 80) throw invalid("Please enter your name.");
  if (input.password.length < 10 || input.password.length > 200) throw invalid("Choose a password of at least 10 characters.");
  const hash = await hashPassword(input.password);
  try {
    return (await one<User>("INSERT INTO users (email, name, password_hash) VALUES ($1,$2,$3) RETURNING id, email, name", [email, name, hash]))!;
  } catch (e) {
    if ((e as { code?: string }).code === "23505") throw new AppError("email_taken", "An account with this email already exists. Sign in instead.", 409);
    throw e;
  }
}

// Verifying against a dummy hash when the user does not exist keeps response time the same either way.
const DUMMY = hashPassword("dummy-password-for-timing");

export async function authenticate(email: string, password: string): Promise<User> {
  const row = await one<User & { password_hash: string }>("SELECT id, email, name, password_hash FROM users WHERE lower(email) = $1", [email.trim().toLowerCase()]);
  const ok = await verifyPassword(password, row?.password_hash ?? (await DUMMY));
  if (!row || !ok) throw new AppError("bad_credentials", "Email or password is incorrect.", 401);
  return { id: row.id, email: row.email, name: row.name };
}

export async function startSession(userId: string) {
  const token = randomToken(32);
  const expires = new Date(Date.now() + SESSION_DAYS * 864e5);
  await q("INSERT INTO sessions (user_id, token_hash, expires_at) VALUES ($1,$2,$3)", [userId, sha256(token), expires]);
  (await cookies()).set(COOKIE, token, { httpOnly: true, sameSite: "lax", secure: env.appUrl.startsWith("https://"), path: "/", expires });
}

export async function endSession() {
  const jar = await cookies();
  const token = jar.get(COOKIE)?.value;
  if (token) await q("DELETE FROM sessions WHERE token_hash = $1", [sha256(token)]);
  jar.delete(COOKIE);
}

export async function currentUser(): Promise<User | null> {
  const token = (await cookies()).get(COOKIE)?.value;
  if (!token) return null;
  return one<User>(
    "SELECT u.id, u.email, u.name FROM sessions s JOIN users u ON u.id = s.user_id WHERE s.token_hash = $1 AND s.expires_at > now()",
    [sha256(token)],
  );
}

export async function requireUser(): Promise<User> {
  const u = await currentUser();
  if (!u) throw unauthorized();
  return u;
}

export type Member = { user: User; business: Business; role: Role };

/**
 * The tenant gate. Resolves the business by slug or id ONLY through the signed-in user's
 * membership, so a business the user does not belong to looks exactly like one that does not exist.
 */
export async function requireMember(slugOrId: string, permission?: Permission): Promise<Member> {
  const user = await requireUser();
  const isId = /^[0-9a-f]{8}-[0-9a-f-]{27}$/i.test(slugOrId);
  const row = await one<Business & { role: Role }>(
    `SELECT ${BUSINESS_COLUMNS}, m.role
       FROM memberships m JOIN businesses b ON b.id = m.business_id
      WHERE m.user_id = $1 AND ${isId ? "b.id = $2" : "b.slug = $2"}`,
    [user.id, slugOrId],
  );
  if (!row) throw notFound("Business not found");
  const { role, ...business } = row;
  if (permission && !can(role, permission)) throw forbidden();
  return { user, business, role };
}

export async function listMemberships(userId: string) {
  return q<{ id: string; slug: string; name: string; role: Role }>(
    "SELECT b.id, b.slug, b.name, m.role FROM memberships m JOIN businesses b ON b.id = m.business_id WHERE m.user_id = $1 ORDER BY b.name",
    [userId],
  );
}

// ---- invitations -------------------------------------------------------------
export async function createInvitation(businessId: string, invitedBy: string, email: string, role: "manager" | "staff"): Promise<string> {
  const e = email.trim().toLowerCase();
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(e)) throw invalid("Please enter a valid email address.");
  const token = randomToken(32);
  await q(
    "INSERT INTO invitations (business_id, email, role, token_hash, invited_by, expires_at) VALUES ($1,$2,$3,$4,$5, now() + interval '7 days')",
    [businessId, e, role, sha256(token), invitedBy],
  );
  return token;
}

export async function getInvitation(token: string) {
  return one<{ id: string; business_id: string; business_name: string; email: string; role: Role }>(
    `SELECT i.id, i.business_id, b.name AS business_name, i.email, i.role FROM invitations i JOIN businesses b ON b.id = i.business_id
      WHERE i.token_hash = $1 AND i.accepted_at IS NULL AND i.expires_at > now()`,
    [sha256(token)],
  );
}

/** The signed-in user must own the invited email address. */
export async function acceptInvitation(token: string, user: User): Promise<string> {
  return tx(async (db) => {
    const inv = await one<{ id: string; business_id: string; email: string; role: Role; slug: string }>(
      `SELECT i.id, i.business_id, i.email, i.role, b.slug FROM invitations i JOIN businesses b ON b.id = i.business_id
        WHERE i.token_hash = $1 AND i.accepted_at IS NULL AND i.expires_at > now() FOR UPDATE OF i`,
      [sha256(token)], db,
    );
    if (!inv) throw new AppError("invite_invalid", "This invitation is no longer valid.", 410);
    if (inv.email !== user.email.toLowerCase()) throw forbidden(`This invitation was sent to ${inv.email}. Sign in with that email to accept it.`);
    await db.query("INSERT INTO memberships (user_id, business_id, role) VALUES ($1,$2,$3) ON CONFLICT (user_id, business_id) DO NOTHING", [user.id, inv.business_id, inv.role]);
    await db.query("UPDATE invitations SET accepted_at = now() WHERE id = $1", [inv.id]);
    return inv.slug;
  });
}
