import { z } from "zod";
import { isValidZone } from "./time";

const hhmm = z.string().regex(/^([01]?\d|2[0-4]):[0-5]\d$/, "Use HH:MM");
const short = (max: number) => z.string().trim().max(max);

export const BUSINESS_TYPES = ["restaurant", "salon", "clinic", "hotel", "repair", "other"] as const;
export const RESOURCE_TYPES = ["table", "staff", "room", "equipment", "slot"] as const;

export const hoursSchema = z.array(z.object({ weekday: z.number().int().min(1).max(7), open: hhmm, close: hhmm })).max(28);

export const policiesSchema = z.object({
  slot_interval_min: z.number().int().min(5).max(240),
  default_duration_min: z.number().int().min(5).max(1440),
  buffer_min: z.number().int().min(0).max(240),
  max_party_size: z.number().int().min(1).max(500),
  min_notice_min: z.number().int().min(0).max(43200),
  max_advance_days: z.number().int().min(1).max(730),
  early_checkin_min: z.number().int().min(0).max(1440),
  late_grace_min: z.number().int().min(0).max(1440),
  cancel_cutoff_min: z.number().int().min(0).max(43200),
  reminder_hours_before: z.number().int().min(0).max(168),
  email_notifications: z.boolean(),
  cancellation_policy: short(1000),
  late_policy: short(1000),
  arrival_instructions: short(1000),
}).partial();

export const profileSchema = z.object({
  name: z.string().trim().min(2).max(80),
  type: z.enum(BUSINESS_TYPES),
  timezone: z.string().refine(isValidZone, "Unknown time zone"),
  description: short(1000),
  address: short(200),
  phone: short(40),
  contact_email: z.union([z.literal(""), z.email().max(160)]),
}).partial();

export const agentSchema = z.object({
  name: z.string().trim().min(1).max(40),
  tone: short(120),
  languages: z.array(z.string().trim().min(2).max(30)).min(1).max(8),
  greeting: short(300),
  extra_instructions: short(2000),
  handoff_contact: short(200),
}).partial();

export const resourcesSchema = z.array(z.object({
  id: z.uuid().optional(),
  name: z.string().trim().min(1).max(60),
  capacity: z.number().int().min(1).max(500),
  type: z.enum(RESOURCE_TYPES).default("table"),
})).max(300);

export const servicesSchema = z.array(z.object({
  id: z.uuid().optional(),
  name: z.string().trim().min(1).max(80),
  description: short(500).default(""),
  duration_min: z.number().int().min(5).max(1440).nullable().default(null),
  price_cents: z.number().int().min(0).max(100_000_000).nullable().default(null),
  currency: short(8).default(""),
  resource_type: z.enum(RESOURCE_TYPES).default("table"),
})).min(1).max(50);

export const faqsSchema = z.array(z.object({ question: z.string().trim().min(2).max(300), answer: z.string().trim().min(1).max(2000) })).max(100);

export const createBusinessSchema = z.object({
  name: z.string().trim().min(2).max(80),
  type: z.enum(BUSINESS_TYPES).default("restaurant"),
  timezone: z.string().refine(isValidZone, "Unknown time zone"),
  description: short(1000).default(""),
  address: short(200).default(""),
  phone: short(40).default(""),
  contact_email: z.union([z.literal(""), z.email().max(160)]).default(""),
  hours: hoursSchema.min(1, "Add at least one opening period"),
  // "4 tables of 2" style input: each row expands into `count` resources.
  capacity: z.array(z.object({ label: short(40).default(""), capacity: z.number().int().min(1).max(500), count: z.number().int().min(1).max(100) })).min(1).max(20),
  service_name: short(80).default(""),
  policies: policiesSchema.default({}),
  agent: agentSchema.default({}),
});
export type CreateBusinessInput = z.infer<typeof createBusinessSchema>;

export const settingsSchema = z.object({
  profile: profileSchema.optional(),
  policies: policiesSchema.optional(),
  hours: hoursSchema.optional(),
  resources: resourcesSchema.optional(),
  services: servicesSchema.optional(),
  agent: agentSchema.optional(),
  faqs: faqsSchema.optional(),
  online_booking_enabled: z.boolean().optional(),
  ai_enabled: z.boolean().optional(),
});
export type SettingsInput = z.infer<typeof settingsSchema>;

export const customerSchema = z.object({
  name: z.string().trim().min(2).max(80),
  email: z.string().trim().max(160).optional().nullable(),
  phone: z.string().trim().max(30).optional().nullable(),
  consent: z.boolean().optional(),
});

export const publicBookingSchema = z.object({
  serviceId: z.uuid().optional().nullable(),
  startsAt: z.iso.datetime({ offset: true }),
  partySize: z.number().int().min(1).max(500),
  customer: customerSchema,
  notes: short(500).optional(),
  idempotencyKey: z.string().min(8).max(100),
  // Honeypot: real visitors never fill this hidden field.
  website: z.string().max(0).optional(),
});
