import { NextResponse } from "next/server";
import { ZodError, type ZodType } from "zod";
import { AppError } from "./errors";
import { log } from "./audit";

type Ctx<P> = { params: Promise<P> };

/**
 * Wraps a route handler: same-origin check for state-changing requests (CSRF defence in addition
 * to SameSite cookies), consistent JSON errors, and no internal details in responses.
 */
export function route<P = Record<string, string>>(fn: (req: Request, params: P) => Promise<unknown>) {
  return async (req: Request, ctx: Ctx<P>) => {
    try {
      if (!["GET", "HEAD", "OPTIONS"].includes(req.method)) assertSameOrigin(req);
      const out = await fn(req, await ctx.params);
      if (out instanceof Response) return out;
      return NextResponse.json(out ?? { ok: true });
    } catch (e) {
      if (e instanceof AppError) {
        return NextResponse.json({ error: { code: e.code, message: e.message, ...(e.data ? { data: e.data } : {}) } }, { status: e.status });
      }
      if (e instanceof ZodError) {
        const first = e.issues[0];
        const where = first?.path?.length ? `${first.path.join(".")}: ` : "";
        return NextResponse.json({ error: { code: "invalid", message: `${where}${first?.message ?? "Invalid input"}` } }, { status: 400 });
      }
      log("error", "unhandled route error", { path: new URL(req.url).pathname, method: req.method, error: (e as Error).message });
      return NextResponse.json({ error: { code: "server_error", message: "Something went wrong on our side. Please try again." } }, { status: 500 });
    }
  };
}

function assertSameOrigin(req: Request) {
  const origin = req.headers.get("origin");
  if (!origin) return; // non-browser clients send no Origin and carry no ambient cookies of a victim
  const host = req.headers.get("x-forwarded-host") ?? req.headers.get("host");
  let originHost = "";
  try { originHost = new URL(origin).host; } catch {}
  if (!host || originHost !== host) throw new AppError("bad_origin", "Cross-site request blocked.", 403);
}

export async function body<T>(req: Request, schema: ZodType<T>, maxBytes = 64_000): Promise<T> {
  const raw = await req.text();
  if (raw.length > maxBytes) throw new AppError("too_large", "Request is too large.", 413);
  let json: unknown;
  try { json = raw ? JSON.parse(raw) : {}; } catch { throw new AppError("invalid", "Invalid JSON.", 400); }
  return schema.parse(json);
}

/** Best-effort client address for rate limiting. Behind a proxy you control, x-forwarded-for is set by it. */
export function clientIp(req: Request): string {
  return (req.headers.get("x-forwarded-for")?.split(",")[0] ?? req.headers.get("x-real-ip") ?? "local").trim().slice(0, 60);
}
