import { z } from "zod";
import { can, requireMember } from "@/lib/auth";
import { createReservation } from "@/lib/booking/reservations";
import { listReservations, parseFilters } from "@/lib/booking/search";
import { body, route } from "@/lib/http";
import { presentReservation } from "@/lib/present";
import { customerSchema } from "@/lib/schemas";
import { ticketToken } from "@/lib/crypto";

type P = { bid: string };

export const GET = route<P>(async (req, { bid }) => {
  const { business, role } = await requireMember(bid, "reservations.read");
  const { rows, total } = await listReservations(business.id, business.timezone, parseFilters(new URL(req.url).searchParams));
  return { total, reservations: rows.map((r) => presentReservation(r, business.timezone, can(role, "customers.full"))) };
});

const manualSchema = z.object({
  serviceId: z.uuid().optional().nullable(),
  startsAt: z.iso.datetime({ offset: true }),
  partySize: z.number().int().min(1).max(500),
  customer: customerSchema,
  notes: z.string().trim().max(500).optional(),
  tentative: z.boolean().optional(),
  idempotencyKey: z.string().min(8).max(100),
});

// Manual booking for phone calls and walk-ins. Recorded with source "staff".
export const POST = route<P>(async (req, { bid }) => {
  const { business, user } = await requireMember(bid, "reservations.create");
  const input = await body(req, manualSchema);
  const made = await createReservation({
    businessId: business.id, serviceId: input.serviceId, startsAt: input.startsAt, partySize: input.partySize,
    customer: input.customer, notes: input.notes, tentative: input.tentative, idempotencyKey: `staff:${input.idempotencyKey}`,
    source: "staff", actor: { type: "staff", userId: user.id },
  });
  return { reservation: presentReservation(made.reservation, business.timezone, true), ticketUrl: `/t/${made.reservation.ticket_id ? ticketToken(made.reservation.ticket_id) : ""}` };
});
